	always @(posedge clk) begin
		if (reset) begin
			q <= 16'b0;
		end else begin
			q <= q + 16'b1;
		end
	end

	// Enable logic
	assign ena[1] = q[3:0] == 4'b0;
	assign ena[2] = q[7:0] == 8'b0;
	assign ena[3] = q[11:0] == 12'b0;
endmodule

	always @(posedge clk) begin
		Y0 <= x & y[0];
		z <= x | y[2];
	end
endmodule



	assign heater = mode & too_cold;
	assign aircon = mode & too_hot;
	assign fan = mode ? (too_cold | too_hot) : fan_on;

endmodule



	assign Y1 = y[0] | y[1] | y[2] | y[3] | y[4] | y[5];
	assign Y3 = w & y[0] & y[1] & y[2] & y[3] & y[4] & y[5];

endmodule
